'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Selector, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './selector.css'

import { CrossGlyph, LockGlyph, StarGlyph, TickGlyph } from './glyphs'
import { Sheet } from './sheet'

/**
 * Selector: one value out of a set.
 *
 * Segmented, dropdown, stepper and the swipe card are the same selection
 * rendered four ways, so they are one component and one state machine, exactly
 * as `choice` is (BDS-010). Four components would mean four accessibility
 * stories and four sets of the same bug.
 *
 * Two facts are kept apart, because the attribute contract keeps them apart.
 * `presentation` is how the control looks: `segmented`, `dropdown`, `stepper`
 * or `card`. `interaction` is how it is worked: `tap`, `hold` or `swipe`.
 * Hold-to-charge and swipe-to-commit are not renderings, so they do not widen
 * the presentation list; every presentation can be tapped, held or swiped,
 * though a card is only ever useful swiped.
 *
 * The interaction attaches to whichever surface commits. In `segmented` and
 * `dropdown` that surface is the option itself: hold an option to charge it,
 * or swipe, where each direction is bound to one option in order. In `stepper`
 * there are no per-option surfaces, so the value face is held, and a swipe
 * left or right commits the previous or next option.
 *
 * It performs nothing. It does not fetch, persist, or decide whether the value
 * is right. The host settles the outcome and passes it back as `result`.
 */

export type SelectorPresentation = 'segmented' | 'dropdown' | 'stepper' | 'card'

export type SelectorInteraction = 'tap' | 'hold' | 'swipe'

export type SelectorSwipe = 'right' | 'left' | 'up' | 'down'

export type SelectorSettled = 'correct' | 'wrong' | 'rewarded'

export type SelectorState = 'idle' | 'selected' | 'committed' | SelectorSettled

export interface SelectorOption {
  id: string
  label: string
  /** Optional supporting line. Never carries meaning that the label does not. */
  detail?: string
  /**
   * What this option won, already formatted and signed: `'+250'`, `'x2'`.
   * Rendered as a badge floating clear of the corner, and only when the option
   * settles `rewarded`. Host-formatted rather than a number, because the sign,
   * the separator and the unit are all the game's to decide. Same field, same
   * rule, as `ChoiceOption.reward`.
   */
  reward?: string
  /** Not available at all. Flat, no padlock. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
}

export interface SelectorResult {
  /** Which options settled which way. Absent ids are left unsettled. */
  [optionId: string]: SelectorSettled
}

export interface SelectorProps {
  options: SelectorOption[]
  /** How it looks. Does not change what it means or how it is announced. */
  presentation?: SelectorPresentation
  /** How it is worked. Orthogonal to the presentation. */
  interaction?: SelectorInteraction
  /** What is being chosen. Rendered as the group's accessible name. */
  label: string
  /**
   * The option that starts selected, by id. Picked and reversible, exactly as
   * if the player had tapped it; nothing is committed. A host restoring a
   * player's earlier pick passes it here.
   */
  defaultSelected?: string
  /**
   * Commit as soon as the player picks, with no separate confirm step. Applies
   * to `tap` only: a hold that has charged and a swipe that has landed are
   * already deliberate acts, so they always commit, and a stepper always needs
   * a separate commit because stepping past a value is not choosing it.
   */
  commitOnSelect?: boolean
  /** Milliseconds of hold to reach a full charge. */
  holdDuration?: number
  /** How many options one step of a stepper moves. */
  increment?: number
  /** Settled outcomes from the host. Presence of this switches to result states. */
  result?: SelectorResult
  /** Locks everything without settling, for a closed round. */
  closed?: boolean
  /** Not available at all. Goes flat, takes no focus. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean

  onSelected?: (optionId: string) => void
  onCommitted?: (optionId: string) => void
  /** Fired on every charge tick, 0 to 100. Cues sound and haptics. */
  onCharge?: (optionId: string, charge: number) => void
  /** Fired once per settled option when `result` arrives. */
  onSettled?: (optionId: string, state: SelectorSettled) => void
}

/**
 * Whether the player is working this by thumb rather than pointer. Read at
 * render, because a device does not change its pointer between two frames and
 * the list is never open on the first render, so a server-rendered selector
 * cannot disagree with the client about it.
 */
const coarsePointer = () =>
  typeof window !== 'undefined' &&
  typeof window.matchMedia === 'function' &&
  window.matchMedia('(pointer: coarse)').matches

/** Glyphs, because colour alone is not an answer. */
const GLYPH: Record<SelectorSettled, React.ReactNode> = {
  correct: <TickGlyph />,
  wrong: <CrossGlyph />,
  rewarded: <StarGlyph filled />,
}

// The padlock is `LockGlyph` from `@gamestage/glyphs`. It was a colour emoji,
// which ignored every colour token and changed silhouette per operating system
// (GSUI-103). The character is not repeated here: the gate greps the source for
// emoji, and a mention would read as a use.

const STATE_LABEL = {
  selected: 'selected',
  committed: 'locked in',
  correct: 'correct',
  wrong: 'wrong',
  rewarded: 'rewarded',
  charging: 'charging',
  locked: 'locked',
  disabled: 'unavailable',
} as const

/**
 * Directions are handed out in this order, so the affirmative swipe of every
 * swipe-card idiom lands on the first option. Past the fourth an option has no
 * direction and is reached by the keyboard or by another presentation.
 */
const SWIPE_ORDER: SelectorSwipe[] = ['right', 'left', 'up', 'down']

const SWIPE_KEY: Record<string, SelectorSwipe> = {
  ArrowRight: 'right',
  ArrowLeft: 'left',
  ArrowUp: 'up',
  ArrowDown: 'down',
}

/** Coarse enough that a tap with a shaky thumb is not read as a gesture. */
const SWIPE_THRESHOLD_PX = 48

/**
 * A fixed tick rather than a frame loop: the charge has to be assertable, and a
 * requestAnimationFrame loop cannot be advanced by a test's clock.
 */
const CHARGE_TICK_MS = 50

export function Selector({
  options,
  presentation = 'segmented',
  interaction = 'tap',
  label,
  defaultSelected,
  commitOnSelect = false,
  holdDuration = 800,
  increment = 1,
  result,
  closed = false,
  disabled = false,
  locked = false,
  onSelected,
  onCommitted,
  onCharge,
  onSettled,
}: SelectorProps) {
  const [selected, setSelected] = React.useState<string | undefined>(defaultSelected)
  const [committed, setCommitted] = React.useState(false)
  const [charge, setCharge] = React.useState(0)
  const [chargingId, setChargingId] = React.useState<string | undefined>(undefined)
  const [open, setOpen] = React.useState(false)
  const [focusIndex, setFocusIndex] = React.useState(0)
  // The direction a swipe card is being dragged towards, before the finger
  // lifts. Interaction state rather than component state: it is the card's
  // `:active`, so it is a class and not an attribute.
  const [dragging, setDragging] = React.useState<SelectorSwipe | undefined>(undefined)

  const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const triggerRef = React.useRef<HTMLButtonElement | null>(null)
  const chargeRef = React.useRef(0)
  const timerRef = React.useRef<ReturnType<typeof setInterval> | undefined>(undefined)
  const dragRef = React.useRef<{ x: number; y: number } | null>(null)
  const settledAlready = React.useRef(new Set<string>())

  // The host settles. Report each outcome once, so a re-render does not replay
  // the sound.
  React.useEffect(() => {
    if (!result) return
    for (const [id, state] of Object.entries(result)) {
      if (settledAlready.current.has(id)) continue
      settledAlready.current.add(id)
      onSettled?.(id, state)
    }
  }, [result, onSettled])

  // A charge left running past unmount keeps firing onCharge into a component
  // that no longer exists.
  React.useEffect(() => stopCharging, [])

  /**
   * Which settled option a surface that shows one should display when the player
   * picked nothing. A host may settle the whole answer key, so "the first one
   * the result names" would show a stepper somebody else's wrong answer as the
   * round's outcome. A settled round with no pick is a results display, so it
   * shows the outcome: correct or rewarded first, and a wrong one only when the
   * host settled nothing else.
   */
  function settledToShow(): number {
    if (!result) return -1
    const won = options.findIndex((option) => {
      const state = result[option.id]
      return state === 'correct' || state === 'rewarded'
    })
    return won >= 0 ? won : options.findIndex((option) => !!result[option.id])
  }

  const selectedIndex = options.findIndex((option) => option.id === selected)
  // A stepper draws one face and a closed dropdown draws one trigger, so one
  // option at a time is all either can show. It shows the player's pick. Failing
  // that, and once the host has settled the round, it shows the option the
  // result names, which is how `choice` behaves too: a settled round renders the
  // outcomes it was given whether or not this player answered. Only then does it
  // fall back to the first option.
  const settledIndex = settledToShow()
  const currentIndex =
    selectedIndex >= 0 ? selectedIndex : settledIndex >= 0 ? settledIndex : 0
  const current = options[currentIndex]

  // A hold that has charged and a swipe that has landed are deliberate, so they
  // commit. A stepper never commits on selection: stepping past a value is not
  // choosing it, and an accidental commit two values early reads as a bug.
  const commits: 'separate' | 'immediate' =
    interaction === 'tap'
      ? commitOnSelect && presentation !== 'stepper'
        ? 'immediate'
        : 'separate'
      : 'immediate'

  // An *empty* result map is not a settled round: it is the value a host holds
  // before anything has settled, and `useState<SelectorResult>({})` is how a
  // React host holds a map it fills over time. `!!result` was true for `{}`, so
  // passing the obvious initial value closed the round on first render and the
  // control did nothing when a player used it. `choice` carried the same defect
  // and was fixed for it; this is the sibling.
  const roundSettled = !!result && Object.keys(result).length > 0

  const closedOut = committed || closed || roundSettled || disabled || locked

  function isDisabled(option: SelectorOption) {
    return !!option.disabled || disabled
  }

  function isBlocked(option: SelectorOption) {
    return isDisabled(option) || !!option.locked || closedOut
  }

  /**
   * What the player did with this option. Independent of how it turned out: a
   * committed option keeps `committed` after the round settles, because
   * committed means locked in and no longer reversible, which a settled option
   * is. Reading the two as one ladder is what dropped the player's own answer
   * off `choice`'s results screen (GSUI-81); the same shape was here.
   */
  function pickOf(option: SelectorOption): 'selected' | 'committed' | undefined {
    if (option.id !== selected) return undefined
    return committed || closed || roundSettled ? 'committed' : 'selected'
  }

  /** How it turned out. The host's fact, not the component's. */
  function settledOf(option: SelectorOption): SelectorSettled | undefined {
    return result?.[option.id]
  }

  /**
   * How the option on show turned out, for the two presentations that show one
   * option rather than all of them. It never claims the player answered: the
   * face and the trigger carry the outcome and no `data-gs-committed`, and a
   * pick always wins the display, so a player who answered sees their own answer
   * settled rather than the right one.
   */
  function shownOutcome(): SelectorSettled | undefined {
    return current ? settledOf(current) : undefined
  }

  /** The one word the accessible name uses: the outcome if there is one, else the pick. */
  function stateOf(option: SelectorOption): SelectorState {
    return settledOf(option) ?? pickOf(option) ?? 'idle'
  }

  // -- swipe ---------------------------------------------------------------
  // Which option each direction commits. For a stepper the directions are the
  // neighbours, which is the same fact the contract states: a direction, and so
  // the option it commits.
  const swipeTargets: Partial<Record<SelectorSwipe, string>> = {}
  if (interaction === 'swipe') {
    if (presentation === 'stepper') {
      const previous = options[currentIndex - increment]
      const next = options[currentIndex + increment]
      if (previous) swipeTargets.left = previous.id
      if (next) swipeTargets.right = next.id
    } else {
      options.forEach((option, index) => {
        const direction = SWIPE_ORDER[index]
        if (direction) swipeTargets[direction] = option.id
      })
    }
  }

  function swipeOf(optionId: string): SelectorSwipe | undefined {
    return SWIPE_ORDER.find((direction) => swipeTargets[direction] === optionId)
  }

  // -- acts ----------------------------------------------------------------
  function select(option: SelectorOption, commit: boolean) {
    if (isBlocked(option)) return
    setSelected(option.id)
    onSelected?.(option.id)
    if (commit) {
      setCommitted(true)
      onCommitted?.(option.id)
    }
  }

  function commitDirection(direction: SelectorSwipe) {
    const id = swipeTargets[direction]
    const option = options.find((candidate) => candidate.id === id)
    if (option) select(option, true)
  }

  function step(delta: number) {
    if (options.length === 0) return
    const next = Math.min(options.length - 1, Math.max(0, currentIndex + delta))
    const option = options[next]
    // A swipe is its own commit, and on a stepper the swipe is the step.
    if (option) select(option, interaction === 'swipe')
  }

  // -- hold ----------------------------------------------------------------
  function stopCharging() {
    if (timerRef.current !== undefined) {
      clearInterval(timerRef.current)
      timerRef.current = undefined
    }
  }

  function releaseHold() {
    stopCharging()
    chargeRef.current = 0
    setCharge(0)
    setChargingId(undefined)
  }

  function startHold(option: SelectorOption) {
    if (isBlocked(option) || timerRef.current !== undefined) return
    chargeRef.current = 0
    setCharge(0)
    setChargingId(option.id)
    const perTick = holdDuration > 0 ? (100 * CHARGE_TICK_MS) / holdDuration : 100
    timerRef.current = setInterval(() => {
      chargeRef.current = Math.min(100, chargeRef.current + perTick)
      setCharge(chargeRef.current)
      onCharge?.(option.id, Math.round(chargeRef.current))
      if (chargeRef.current >= 100) {
        releaseHold()
        select(option, true)
      }
    }, CHARGE_TICK_MS)
  }

  /**
   * The charge a surface renders. A committed hold stays at 100 rather than
   * snapping back, because the bar is the record of what the player did.
   */
  function chargeOf(option: SelectorOption): number | undefined {
    if (interaction !== 'hold') return undefined
    if (option.id === chargingId) return Math.round(charge)
    if (committed && option.id === selected) return 100
    return 0
  }

  function holdHandlers(option: SelectorOption) {
    if (interaction !== 'hold') return {}
    return {
      onPointerDown: () => startHold(option),
      onPointerUp: () => releaseHold(),
      onPointerLeave: () => releaseHold(),
      onPointerCancel: () => releaseHold(),
      onBlur: () => releaseHold(),
    }
  }

  /**
   * The keyboard equivalent of a hold. The design has not settled one, so this
   * is a decision rather than a specification: Space held charges, and Enter
   * commits outright. Space is the hold because a held key repeats and the
   * repeats are ignorable; Enter is there because a player who cannot hold a
   * key at all still has to be able to commit, and a control only one of them
   * can work is not keyboard operable.
   */
  function holdKeys(option: SelectorOption) {
    return {
      down(event: React.KeyboardEvent) {
        if (event.key === ' ') {
          event.preventDefault()
          if (!event.repeat) startHold(option)
          return true
        }
        if (event.key === 'Enter') {
          event.preventDefault()
          select(option, true)
          return true
        }
        return false
      },
      up(event: React.KeyboardEvent) {
        if (event.key === ' ') {
          event.preventDefault()
          releaseHold()
        }
      },
    }
  }

  // -- roving focus --------------------------------------------------------
  function moveFocus(to: number) {
    if (options.length === 0) return
    const next = (to + options.length) % options.length
    setFocusIndex(next)
    optionRefs.current[next]?.focus()
    // Arrow keys in a radiogroup move and select together. They only select
    // when a tap would have: a hold has not been held, and a swipe has its own
    // keys below.
    const option = options[next]
    if (interaction === 'tap' && option) select(option, commits === 'immediate')
  }

  function closeList(returnFocus = true) {
    setOpen(false)
    if (returnFocus) triggerRef.current?.focus()
  }

  React.useEffect(() => {
    if (presentation !== 'dropdown' || !open) return
    const index = selectedIndex >= 0 ? selectedIndex : 0
    setFocusIndex(index)
    optionRefs.current[index]?.focus()
  }, [open, presentation, selectedIndex])

  function optionKeyDown(option: SelectorOption, index: number) {
    return (event: React.KeyboardEvent) => {
      if (presentation === 'dropdown' && open) {
        if (event.key === 'Escape') {
          event.preventDefault()
          closeList()
          return
        }
        // Tabbing out closes it but does not claw the focus back: the player
        // asked to leave, and a list left open behind them is a control the
        // keyboard can land in again by accident.
        if (event.key === 'Tab') {
          closeList(false)
          return
        }
      }
      if (interaction === 'hold' && holdKeys(option).down(event)) return
      if (interaction === 'swipe' && presentation !== 'dropdown') {
        const direction = SWIPE_KEY[event.key]
        if (direction) {
          event.preventDefault()
          commitDirection(direction)
          return
        }
      }
      switch (event.key) {
        case 'ArrowRight':
        case 'ArrowDown':
          event.preventDefault()
          moveFocus(index + 1)
          break
        case 'ArrowLeft':
        case 'ArrowUp':
          event.preventDefault()
          moveFocus(index - 1)
          break
        case 'Home':
          event.preventDefault()
          moveFocus(0)
          break
        case 'End':
          event.preventDefault()
          moveFocus(options.length - 1)
          break
      }
    }
  }

  // -- pointer swipe, on the root so any surface of the control carries it ---
  const directionOf = (dx: number, dy: number): SelectorSwipe =>
    Math.abs(dx) >= Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : dy > 0 ? 'down' : 'up'

  const swipeSurface =
    interaction === 'swipe'
      ? {
          onPointerDown: (event: React.PointerEvent) => {
            dragRef.current = { x: event.clientX, y: event.clientY }
          },
          // The card leans the way it is being thrown and shows the badge of
          // the option it would commit, from a quarter of the way to the
          // threshold, so the player sees the answer before letting go.
          onPointerMove: (event: React.PointerEvent) => {
            const start = dragRef.current
            if (!start || presentation !== 'card') return
            const dx = event.clientX - start.x
            const dy = event.clientY - start.y
            const far = Math.max(Math.abs(dx), Math.abs(dy)) >= SWIPE_THRESHOLD_PX / 4
            const direction = far ? directionOf(dx, dy) : undefined
            setDragging(direction && swipeTargets[direction] ? direction : undefined)
          },
          onPointerUp: (event: React.PointerEvent) => {
            const start = dragRef.current
            dragRef.current = null
            setDragging(undefined)
            if (!start) return
            const dx = event.clientX - start.x
            const dy = event.clientY - start.y
            if (Math.max(Math.abs(dx), Math.abs(dy)) < SWIPE_THRESHOLD_PX) return
            commitDirection(directionOf(dx, dy))
          },
          onPointerCancel: () => {
            dragRef.current = null
            setDragging(undefined)
          },
        }
      : {}

  // -- naming --------------------------------------------------------------
  // The accessible name carries the state, because a screen reader user gets no
  // fill, no stroke and no glyph. It also carries the gesture, because a hold
  // and a swipe are otherwise invisible.
  function nameOf(option: SelectorOption) {
    const words = [option.label]
    const state = stateOf(option)
    if (option.id === chargingId) words.push(STATE_LABEL.charging)
    else if (state !== 'idle') words.push(STATE_LABEL[state])
    // The reward badge is a drawing, so the amount has to be here too. Being
    // told you were rewarded without being told what with is worse than not
    // being told at all.
    if (state === 'rewarded' && option.reward) words.push(option.reward)
    if (option.locked) words.push(STATE_LABEL.locked)
    if (isDisabled(option)) words.push(STATE_LABEL.disabled)
    // A hint is for a surface at rest. Repeating 'hold to commit' at a
    // control already being held is noise at exactly the wrong moment.
    if (!isBlocked(option) && state === 'idle' && option.id !== chargingId) {
      if (interaction === 'hold') words.push('hold to commit')
      const direction = swipeOf(option.id)
      if (direction) words.push(`swipe ${direction}`)
    }
    return words.join(', ')
  }

  /**
   * The glyph and the reward badge a settled surface shows. Shared, because the
   * stepper's face and the dropdown's trigger are not options and so never
   * reached `optionMarkers`: every result style was scoped to
   * `.gs-selector__option`, and a settled stepper or a settled closed dropdown
   * drew nothing at all (GSUI-82). BDS-012 changes three things at once, and
   * the glyph is the one a colour-blind player reads.
   */
  function settledMarkers(option: SelectorOption, state: SelectorSettled) {
    return (
      <>
        <span
          className="gs-selector__glyph"
          data-gs-scope="selector" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {GLYPH[state]}
        </span>
        {/* The amount won, floating clear of the corner rather than sitting
            inside the control (BDS-012, specimen 2b). Hidden, because `nameOf`
            already carries it. `delta` is the part vocabulary's word for a
            signed change, which is what this is. */}
        {state === 'rewarded' && option.reward ? (
          <span
            className="gs-selector__reward"
            data-gs-scope="selector" data-gs-part="delta"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            {option.reward}
          </span>
        ) : null}
      </>
    )
  }

  function optionMarkers(option: SelectorOption) {
    const state = stateOf(option)
    const settled = state === 'correct' || state === 'wrong' || state === 'rewarded'
    return (
      <>
        <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
          {option.label}
        </span>
        {option.detail ? <span className="gs-selector__detail">{option.detail}</span> : null}
        {interaction === 'hold' ? (
          <>
            {/* The charge sweeps across the whole surface behind the words,
                as specimen 1j draws it, and the percentage sits at the far
                end. Both are hidden: `nameOf` carries "charging". */}
            <span
              className="gs-selector__charge"
              data-gs-scope="selector" data-gs-part="charge"
              data-gs-animates="emphasis"
              aria-hidden="true"
            >
              <span
                className="gs-selector__charge-fill"
                style={{ width: `${chargeOf(option) ?? 0}%` }}
              />
            </span>
            <span
              className="gs-selector__value gs-display-type"
              data-gs-scope="selector" data-gs-part="value"
              aria-hidden="true"
            >
              {chargeOf(option) ?? 0}%
            </span>
          </>
        ) : null}
        {option.locked ? (
          <span className="gs-selector__glyph" data-gs-scope="selector" data-gs-part="glyph" aria-hidden="true">
            <LockGlyph />
          </span>
        ) : settled ? (
          settledMarkers(option, state as SelectorSettled)
        ) : null}
      </>
    )
  }

  function optionAttributes(option: SelectorOption) {
    const state = stateOf(option)
    const settled = state === 'correct' || state === 'wrong' || state === 'rewarded'
    return {
      'data-gs-choice': option.id,
      'data-gs-selected': pickOf(option) === 'selected' ? 'true' : undefined,
      'data-gs-committed': pickOf(option) === 'committed' ? 'true' : undefined,
      'data-gs-state': settledOf(option),
      'data-gs-disabled': isDisabled(option) ? 'true' : undefined,
      'data-gs-locked': option.locked || locked ? 'true' : undefined,
      'data-gs-charge': chargeOf(option),
      'data-gs-swipe': swipeOf(option.id),
      'data-gs-elevation': 'raised' as const,
      // The surface moves on press. Its fill and glyph are emphasis and survive
      // reduced motion, which is how a player who cannot see movement still
      // gets the answer.
      'data-gs-animates': 'motion' as const,
    }
  }

  function renderOption(option: SelectorOption, index: number, inList: boolean) {
    const chosen = !!pickOf(option)
    const role = inList ? 'option' : interaction === 'tap' ? 'radio' : undefined
    return (
      <button
        key={option.id}
        ref={(node) => {
          optionRefs.current[index] = node
        }}
        type="button"
        className="gs-selector__option gs-action-type"
        {...optionAttributes(option)}
        role={role}
        aria-checked={role === 'radio' ? chosen : undefined}
        aria-selected={role === 'option' ? chosen : undefined}
        aria-pressed={role === undefined ? chosen : undefined}
        aria-label={nameOf(option)}
        aria-disabled={isBlocked(option) || undefined}
        disabled={isDisabled(option)}
        tabIndex={index === focusIndex ? 0 : -1}
        onFocus={() => setFocusIndex(index)}
        onClick={() => {
          if (interaction !== 'tap') return
          select(option, commits === 'immediate')
          if (inList) closeList()
        }}
        onKeyDown={optionKeyDown(option, index)}
        onKeyUp={interaction === 'hold' ? holdKeys(option).up : undefined}
        {...holdHandlers(option)}
      >
        {optionMarkers(option)}
      </button>
    )
  }

  // -- presentations -------------------------------------------------------
  function renderSegmented() {
    return (
      <div className="gs-selector__track" data-gs-scope="selector" data-gs-part="track">
        {options.map((option, index) => renderOption(option, index, false))}
      </div>
    )
  }

  function renderDropdown() {
    // What the trigger stands for: the pick, or the settled option once the
    // round is over. A closed dropdown renders only the trigger, so without this
    // a settled dropdown showed the answer to anybody who opened the list and
    // nothing at all to everybody else.
    const shown = selectedIndex >= 0 || settledIndex >= 0 ? current : undefined
    const settled = shownOutcome()
    const triggerWords = [label, shown ? nameOf(shown) : 'nothing selected']
    const list = (
      <div
        className="gs-selector__list"
        data-gs-scope="selector" data-gs-part="list"
        data-gs-elevation="raised"
        role="listbox"
        aria-label={label}
      >
        {options.map((option, index) => renderOption(option, index, true))}
      </div>
    )
    return (
      <>
        <button
          ref={triggerRef}
          type="button"
          className="gs-selector__trigger gs-action-type"
          data-gs-scope="selector" data-gs-part="trigger"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-disabled={disabled ? 'true' : undefined}
          data-gs-locked={locked ? 'true' : undefined}
          data-gs-state={settled}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-label={triggerWords.join(', ')}
          aria-disabled={closedOut || undefined}
          disabled={disabled}
          onClick={() => {
            if (closedOut) return
            setOpen((wasOpen) => !wasOpen)
          }}
          onKeyDown={(event) => {
            if (closedOut) return
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
              event.preventDefault()
              setOpen(true)
            }
          }}
        >
          <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
            {shown ? shown.label : label}
          </span>
          {settled && shown ? settledMarkers(shown, settled) : null}
        </button>
        {/* On touch the list opens as a sheet at the foot of the surface, which
            is specimen 5c's rule for a select (GSUI-196): a thumb cannot use a
            list hanging under a trigger the way a pointer can. The same option
            elements, the same listbox, the same keys; only where they sit
            changes. The sheet closes on its scrim and on Escape, and hands
            focus back to the trigger, the way closeList does. */}
        {open ? (
          coarsePointer() ? (
            <Sheet open onDismiss={() => closeList()} label={label}>
              {list}
            </Sheet>
          ) : (
            list
          )
        ) : null}
      </>
    )
  }

  function renderStepper() {
    const previous = options[currentIndex - increment]
    const next = options[currentIndex + increment]
    const hold = current ? holdKeys(current) : undefined
    // The face is the whole of a stepper's drawing, so it is where the outcome
    // has to land.
    const settled = shownOutcome()
    return (
      <div className="gs-selector__track" data-gs-scope="selector" data-gs-part="track">
        <button
          type="button"
          className="gs-selector__step"
          data-gs-scope="selector" data-gs-part="decrement"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-swipe={interaction === 'swipe' && previous ? 'left' : undefined}
          aria-label={`previous ${label}`}
          aria-disabled={(closedOut || !previous) || undefined}
          disabled={disabled}
          onClick={() => step(-increment)}
        >
          <span aria-hidden="true">−</span>
        </button>
        <div
          className="gs-selector__face gs-action-type"
          data-gs-scope="selector" data-gs-part="face"
          data-gs-elevation="raised"
          data-gs-charge={current ? chargeOf(current) : undefined}
          data-gs-state={settled}
          data-gs-animates="motion"
          role="spinbutton"
          tabIndex={disabled ? -1 : 0}
          aria-label={label}
          aria-valuenow={options.length === 0 ? undefined : currentIndex + 1}
          aria-valuemin={1}
          aria-valuemax={options.length}
          aria-valuetext={current ? nameOf(current) : 'nothing selected'}
          aria-disabled={closedOut || undefined}
          onKeyDown={(event) => {
            if (interaction === 'hold' && current && hold?.down(event)) return
            switch (event.key) {
              case 'ArrowRight':
              case 'ArrowUp':
                event.preventDefault()
                step(increment)
                break
              case 'ArrowLeft':
              case 'ArrowDown':
                event.preventDefault()
                step(-increment)
                break
              case 'Home':
                event.preventDefault()
                step(-options.length)
                break
              case 'End':
                event.preventDefault()
                step(options.length)
                break
            }
          }}
          onKeyUp={interaction === 'hold' && hold ? hold.up : undefined}
          {...(current ? holdHandlers(current) : {})}
        >
          <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
            {current ? current.label : label}
          </span>
          {current?.detail ? <span className="gs-selector__detail">{current.detail}</span> : null}
          {interaction === 'hold' ? (
            <span
              className="gs-selector__charge"
              data-gs-scope="selector" data-gs-part="charge"
              data-gs-animates="emphasis"
              aria-hidden="true"
            >
              <span
                className="gs-selector__charge-fill"
                style={{ width: `${(current && chargeOf(current)) || 0}%` }}
              />
            </span>
          ) : null}
          {settled && current ? settledMarkers(current, settled) : null}
        </div>
        <button
          type="button"
          className="gs-selector__step"
          data-gs-scope="selector" data-gs-part="increment"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-swipe={interaction === 'swipe' && next ? 'right' : undefined}
          aria-label={`next ${label}`}
          aria-disabled={(closedOut || !next) || undefined}
          disabled={disabled}
          onClick={() => step(increment)}
        >
          <span aria-hidden="true">+</span>
        </button>
      </div>
    )
  }

  const selectedOption = options.find((option) => option.id === selected)

  /**
   * The swipe card, specimen 1j. One face carries the question; each option is
   * written along the bottom edge with the arrow of its direction; a badge for
   * the option a drag is heading for appears in the top corner. A second card
   * peeks out underneath, because a card that stands alone is a panel and a
   * card on a deck is something to throw.
   *
   * The face is the one keyboard stop: the arrow keys commit the option bound
   * to that direction, which is the same map a segmented swipe uses. The
   * options are written, not buttons, because a swipe card's options are its
   * two edges rather than two things to press.
   */
  function renderCard() {
    // Written in the order they sit on the card, left edge first, so "No" is
    // on the left when a swipe left commits it. SWIPE_ORDER is the order
    // directions are handed out, which is a different fact.
    const EDGE_ORDER: SelectorSwipe[] = ['left', 'up', 'down', 'right']
    const bound = EDGE_ORDER.filter((direction) => swipeTargets[direction])
    const optionByDirection = (direction: SelectorSwipe) =>
      options.find((option) => option.id === swipeTargets[direction])
    const ARROW: Record<SelectorSwipe, [string, string]> = {
      left: ['← ', ''],
      right: ['', ' →'],
      up: ['↑ ', ''],
      down: ['', ' ↓'],
    }
    const words = [label]
    for (const direction of bound) {
      const option = optionByDirection(direction)
      if (option) words.push(`swipe ${direction} for ${option.label}`)
    }
    const chosen = selectedOption
    if (chosen) words.push(`${chosen.label} ${committed ? STATE_LABEL.committed : STATE_LABEL.selected}`)
    return (
      <div className="gs-selector__deck">
        <span className="gs-selector__deck-back" aria-hidden="true" />
        <div
          className={['gs-selector__face', dragging ? `gs-selector__face--${dragging}` : '']
            .filter(Boolean)
            .join(' ')}
          data-gs-scope="selector" data-gs-part="face"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-committed={committed ? 'true' : undefined}
          role="group"
          tabIndex={disabled ? -1 : 0}
          aria-label={words.join(', ')}
          aria-disabled={closedOut || undefined}
          onKeyDown={(event) => {
            if (closedOut) return
            const direction = SWIPE_KEY[event.key]
            if (direction && swipeTargets[direction]) {
              event.preventDefault()
              commitDirection(direction)
            }
          }}
        >
          <div className="gs-selector__head">
            <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
              {label}
            </span>
            {/* One badge per horizontal direction, revealed by the drag. The
                cross is the left throw and the tick the right, which is the
                swipe-card idiom SWIPE_ORDER already encodes: the affirmative
                lands on the first option. */}
            {(['left', 'right'] as const)
              .filter((direction) => swipeTargets[direction])
              .map((direction) => (
                <span
                  key={direction}
                  className="gs-selector__badge"
                  data-gs-scope="selector" data-gs-part="glyph"
                  data-gs-swipe={direction}
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  {direction === 'left' ? <CrossGlyph /> : <TickGlyph />}
                </span>
              ))}
          </div>
          <div className="gs-selector__foot">
            {bound.map((direction) => {
              const option = optionByDirection(direction)
              if (!option) return null
              const [before, after] = ARROW[direction]
              return (
                <span
                  key={option.id}
                  className="gs-selector__edge"
                  data-gs-scope="selector" data-gs-part="row"
                  {...optionAttributes(option)}
                  data-gs-elevation={undefined}
                  data-gs-animates={undefined}
                >
                  {before}
                  {option.label}
                  {after}
                </span>
              )
            })}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className="gs-selector"
      data-gs-component="selector"
      data-gs-presentation={presentation}
      data-gs-interaction={interaction}
      data-gs-commits={commits}
      data-gs-increment={presentation === 'stepper' ? increment : undefined}
      data-gs-disabled={disabled ? 'true' : undefined}
      data-gs-locked={locked ? 'true' : undefined}
      // The host's word for a round that is over, not the player's. A player
      // committing is already visible as `data-gs-committed`, and a settled
      // round as `data-gs-state`.
      data-gs-closed={closed ? 'true' : undefined}
      data-gs-elevation="raised"
      role={presentation === 'segmented' && interaction === 'tap' ? 'radiogroup' : 'group'}
      aria-label={label}
      aria-disabled={closedOut || undefined}
      {...swipeSurface}
    >
      {presentation === 'segmented' ? renderSegmented() : null}
      {presentation === 'dropdown' ? renderDropdown() : null}
      {presentation === 'stepper' ? renderStepper() : null}
      {presentation === 'card' ? renderCard() : null}

      {commits === 'separate' && !closedOut && selectedOption ? (
        <button
          type="button"
          className="gs-selector__commit gs-action-type gs-pressable"
          data-gs-scope="selector" data-gs-part="commit"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          onClick={() => select(selectedOption, true)}
        >
          Lock it in
        </button>
      ) : null}
    </div>
  )
}

/* Selector. Every value comes from a token; nothing here is a literal colour.

   Specimen 1j draws three of these and design/twins/1j.json measures ours
   against each: a segmented tray with flat segments and one raised in the
   interactive colour, a hold-to-charge bar with the charge sweeping behind the
   words and a percentage at the far end, and a swipe card on a deck with the
   direction badge in its corner. The dropdown and the stepper keep the raised
   control look the library already had. */

.gs-selector {
  display: grid;
  gap: var(--gs-space-3);
  position: relative;
  justify-items: stretch;
}

/* The track holds whatever the presentation lays out. Segments sit in a row,
   a stepper sits as minus, face, plus. */
.gs-selector__track {
  display: flex;
  align-items: stretch;
  gap: var(--gs-space-2);
}

.gs-selector[data-gs-presentation='stepper'] .gs-selector__track {
  align-items: center;
  justify-content: start;
}

/* -- the pressable surfaces ----------------------------------------------- */
/* Controls are raised (BDS-040), and a raised control never fades or darkens on
   press: it moves (BDS-013). */
.gs-selector__option,
.gs-selector__trigger,
.gs-selector__step,
.gs-selector__face,
.gs-selector__commit {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: var(--gs-space-1);
  position: relative;

  /* 48px is the smallest target a thumb reliably hits. */
  min-height: var(--gs-size-touch-min);
  padding: var(--gs-space-3) var(--gs-space-4);

  text-align: left;

  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-raised);
  cursor: pointer;

  /* Only the movement is timed here. Fill, glyph and charge transitions live on
     the emphasis elements so they survive reduced motion. */
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

.gs-selector__option {
  flex: 1 1 0;
  /* "Top 3" broke into two lines in a 106px segment; a segment's word is
     one line and the segment grows or the row wraps, never the word. */
  white-space: nowrap;
  min-inline-size: 0;
}

.gs-selector__option:focus-visible,
.gs-selector__trigger:focus-visible,
.gs-selector__step:focus-visible,
.gs-selector__face:focus-visible,
.gs-selector__commit:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

.gs-selector__option:hover:not([aria-disabled='true']),
.gs-selector__trigger:hover:not([aria-disabled='true']),
.gs-selector__step:hover:not([aria-disabled='true']),
.gs-selector__face:hover:not([aria-disabled='true']) {
  border-color: var(--gs-color-edge-high);
}

.gs-selector__option:active:not([aria-disabled='true']),
.gs-selector__trigger:active:not([aria-disabled='true']),
.gs-selector__step:active:not([aria-disabled='true']),
.gs-selector__face:active:not([aria-disabled='true']) {
  transform: translateY(3px);
  box-shadow: var(--gs-depth-flat);
}

/* -- the segmented tray (specimen 1j) ------------------------------------- */
/* A bordered surface holding flat segments. The chosen segment is the one
   raised object in the tray: the interactive colour on a pressable base. The
   hold interaction has its own shape below and does not use the tray. */
.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__track {
  box-sizing: border-box;
  gap: var(--gs-space-2);
  padding: var(--gs-space-2);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
}

.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option {
  box-sizing: border-box;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1) var(--gs-space-2);
  min-height: var(--gs-size-control-medium);
  padding: 0 var(--gs-space-3);
  text-align: center;
  color: var(--gs-color-ink-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--gs-radius-sm);
  box-shadow: var(--gs-depth-flat);
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out,
              background-color var(--gs-motion-emphasis) ease-out;
}

.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option:hover:not([aria-disabled='true']) {
  color: var(--gs-color-ink);
}

.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option[data-gs-selected='true'],
.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option[data-gs-committed='true'] {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: 0;
  box-shadow: var(--gs-depth-pressable);
}

.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option[data-gs-committed='true'] {
  box-shadow: var(--gs-depth-pressable-pressed);
}

.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option:active:not([aria-disabled='true']) {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}

/* A flat segment has no corner to park a mark in, so its padlock or outcome
   glyph and its reward badge sit in the row beside the label. */
.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__glyph {
  position: static;
  font-size: var(--gs-size-icon-utility);
}

/* The swipe chevron, likewise: in the row beside the label rather than parked
   on the corner it does not have. */
.gs-selector[data-gs-presentation='segmented']:not([data-gs-interaction='hold']) .gs-selector__option[data-gs-swipe]::after {
  position: static;
  flex: 0 0 auto;
}

/* -- the stepper ---------------------------------------------------------- */
.gs-selector__step {
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  min-width: var(--gs-size-touch-min);
  padding: 0;
  font-size: var(--gs-size-icon-control);
}

.gs-selector__face {
  flex: 1 1 auto;
  min-width: var(--gs-size-action-large);
  align-items: center;
  text-align: center;
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
}

/* -- the dropdown --------------------------------------------------------- */
.gs-selector__trigger { width: 100%; }

.gs-selector__list {
  display: grid;
  gap: var(--gs-space-1);
  padding: var(--gs-space-2);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-floating);
}

/* Inside a sheet the list is the sheet's content and not a card of its own:
   the sheet already draws the surface, the edge and the depth, and a card
   inside a card is two outlines a pixel apart. */
.gs-sheet .gs-selector__list {
  padding: 0;
  background: none;
  border: 0;
  box-shadow: var(--gs-depth-flat);
}

/* -- selection and commitment --------------------------------------------- */
.gs-selector__option[data-gs-selected='true'],
.gs-selector__face[data-gs-charge]:not([data-gs-charge='0']) {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
}

.gs-selector__option[data-gs-committed='true'] {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
  box-shadow: var(--gs-depth-flat);
}

/* -- hold to charge (specimen 1j) ------------------------------------------ */
/* One wide bar per option, stacked: the words at the left, the percentage at
   the right, and the charge sweeping across the whole surface behind them.
   The ring is drawn at the selected stroke in every state, so it does not
   jump when the hold begins and the ring turns the selected colour. */
.gs-selector[data-gs-interaction='hold'] .gs-selector__track {
  flex-direction: column;
  align-items: stretch;
  gap: var(--gs-space-gap);
}

.gs-selector[data-gs-interaction='hold'] .gs-selector__option,
.gs-selector[data-gs-interaction='hold'] .gs-selector__face {
  box-sizing: border-box;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: var(--gs-space-3);
  height: var(--gs-size-action-large);
  min-height: var(--gs-size-action-large);
  padding: 0 var(--gs-space-6);
  overflow: hidden;
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-selected) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-raised);
  user-select: none;
  touch-action: none;
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out,
              border-color var(--gs-motion-emphasis) ease-out,
              background-color var(--gs-motion-emphasis) ease-out;
}

/* The words and the number sit over the charge. */
.gs-selector[data-gs-interaction='hold'] .gs-selector__label,
.gs-selector[data-gs-interaction='hold'] .gs-selector__detail,
.gs-selector[data-gs-interaction='hold'] .gs-selector__value {
  position: relative;
  z-index: 1;
}

.gs-selector__value {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: normal;
  text-shadow: none;
}

/* The charge is emphasis, not motion: it is a fill that reports progress, and a
   player under reduced motion still has to be able to see the hold landing. */
.gs-selector__charge {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

/* The drawing tints this with the interactive colour at 55%, a token request
   recorded on its twin pair; the solid interactive colour stands in for it. */
.gs-selector__charge-fill {
  display: block;
  height: 100%;
  background: var(--gs-color-interactive-solid);
  transition: width var(--gs-motion-emphasis) linear,
              background-color var(--gs-motion-emphasis) ease-out;
}

/* Being held: the ring turns the selected colour and the bar sits down on its
   base, the way a pressed control does. */
.gs-selector[data-gs-interaction='hold'] .gs-selector__option[data-gs-charge]:not([data-gs-charge='0']):not([data-gs-charge='100']),
.gs-selector[data-gs-interaction='hold'] .gs-selector__face[data-gs-charge]:not([data-gs-charge='0']):not([data-gs-charge='100']) {
  border-color: var(--gs-color-selected);
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-flat);
}

/* Charged: the bar becomes the reward, ringed and glowing, and the fill goes
   because the whole surface is now the colour. */
.gs-selector[data-gs-interaction='hold'] .gs-selector__option[data-gs-charge='100'],
.gs-selector[data-gs-interaction='hold'] .gs-selector__face[data-gs-charge='100'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-color: var(--gs-color-reward-solid);
  box-shadow: var(--gs-depth-reward);
}

.gs-selector__option[data-gs-charge='100'] .gs-selector__charge-fill,
.gs-selector__face[data-gs-charge='100'] .gs-selector__charge-fill {
  background: transparent;
}

/* -- swipe ---------------------------------------------------------------- */
/* The direction a surface commits is a fact a theme may want to draw, and it is
   the only thing that says which way to throw the card. */
.gs-selector[data-gs-interaction='swipe'] .gs-selector__option {
  touch-action: none;
}

.gs-selector__option[data-gs-swipe]::after {
  content: '';
  position: absolute;
  inset: auto var(--gs-space-2) var(--gs-space-2) auto;
  width: var(--gs-space-2);
  height: var(--gs-space-2);
  border-top: var(--gs-stroke-selected) solid var(--gs-color-ink-secondary);
  border-right: var(--gs-stroke-selected) solid var(--gs-color-ink-secondary);
}

.gs-selector__option[data-gs-swipe='right']::after { transform: rotate(45deg); }
.gs-selector__option[data-gs-swipe='left']::after  { transform: rotate(-135deg); }
.gs-selector__option[data-gs-swipe='up']::after    { transform: rotate(-45deg); }
.gs-selector__option[data-gs-swipe='down']::after  { transform: rotate(135deg); }

/* -- the swipe card (specimen 1j) ------------------------------------------ */
/* A raised card on a deck. The card underneath is drawn in the surface colour,
   set down and in by a step, and the face carries the question, the edges and
   the badge. While the face is being dragged it leans the way it is going. */
.gs-selector__deck {
  position: relative;
}

.gs-selector__deck-back {
  position: absolute;
  top: var(--gs-space-3);
  right: var(--gs-space-4);
  bottom: 0;
  left: var(--gs-space-4);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
}

.gs-selector[data-gs-presentation='card'] .gs-selector__face {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: stretch;
  gap: var(--gs-space-6);
  min-width: 0;
  min-height: auto;
  margin-bottom: var(--gs-space-3);
  padding: var(--gs-space-4);
  text-align: left;
  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-xl);
  box-shadow: var(--gs-depth-raised);
  cursor: grab;
  user-select: none;
  touch-action: none;
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

.gs-selector[data-gs-presentation='card'] .gs-selector__face:active:not([aria-disabled='true']) {
  transform: none;
  box-shadow: var(--gs-depth-raised);
  cursor: grabbing;
}

/* The lean: a small turn and a step sideways, as drawn mid-throw. */
.gs-selector[data-gs-presentation='card'] .gs-selector__face--left,
.gs-selector[data-gs-presentation='card'] .gs-selector__face--left:active {
  transform: rotate(-4deg) translateX(calc(-1 * var(--gs-space-inset)));
}

.gs-selector[data-gs-presentation='card'] .gs-selector__face--right,
.gs-selector[data-gs-presentation='card'] .gs-selector__face--right:active {
  transform: rotate(4deg) translateX(var(--gs-space-inset));
}

.gs-selector__head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--gs-space-3);
}

.gs-selector[data-gs-presentation='card'] .gs-selector__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* The badge: a ring in the outcome's colour with its mark, turned a little,
   hidden until the drag heads its way. Emphasis, so it survives reduced
   motion; the lean above is the part that does not. */
.gs-selector__badge {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--gs-size-control-medium);
  height: var(--gs-size-control-medium);
  box-sizing: border-box;
  font-size: var(--gs-size-icon-utility);
  color: var(--gs-color-negative-solid);
  border: var(--gs-stroke-selected) solid var(--gs-color-negative-solid);
  border-radius: var(--gs-radius-full);
  transform: rotate(-12deg);
  opacity: 0;
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-selector__badge[data-gs-swipe='right'] {
  color: var(--gs-color-positive-solid);
  border-color: var(--gs-color-positive-solid);
  transform: rotate(12deg);
}

/* Two badges share one corner; the one not in play takes no room. */
.gs-selector__badge[data-gs-swipe='right'] { margin-left: calc(-1 * var(--gs-size-control-medium)); }

.gs-selector__face--left .gs-selector__badge[data-gs-swipe='left'],
.gs-selector__face--right .gs-selector__badge[data-gs-swipe='right'],
.gs-selector__face[data-gs-committed='true'] .gs-selector__badge[data-gs-swipe='right'] {
  opacity: 1;
}

.gs-selector__foot {
  display: flex;
  justify-content: space-between;
  gap: var(--gs-space-3);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-muted);
}

.gs-selector__edge[data-gs-committed='true'] {
  color: var(--gs-color-ink);
}

/* -- settled outcomes ----------------------------------------------------- */
/* Three things at once: the fill or stroke, a glyph, and the text (BDS-012).
   The face and the trigger are listed beside the option because a stepper
   renders no options at all and a closed dropdown renders only its trigger, so
   scoping these to `.gs-selector__option` left two of the three presentations
   showing nothing when the round settled (GSUI-82). */
.gs-selector__option[data-gs-state='correct'],
.gs-selector__face[data-gs-state='correct'],
.gs-selector__trigger[data-gs-state='correct'] {
  background: var(--gs-color-positive);
  color: var(--gs-color-on-bright);
  border-color: var(--gs-color-positive-base);
}

.gs-selector__option[data-gs-state='wrong'],
.gs-selector__face[data-gs-state='wrong'],
.gs-selector__trigger[data-gs-state='wrong'] {
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) dashed var(--gs-color-negative-solid);
  color: var(--gs-color-ink-secondary);
}
.gs-selector__option[data-gs-state='wrong'] .gs-selector__label,
.gs-selector__face[data-gs-state='wrong'] .gs-selector__label,
.gs-selector__trigger[data-gs-state='wrong'] .gs-selector__label {
  text-decoration: line-through;
}

/* Rewarded is a ring and a glow around the control, never a fill (BDS-012).
   `depth.reward` is both in one token. This used to fill with `color.reward`
   and switch the ink, which made it the same drawing as `correct` with a
   different hue: a reward read as a second kind of right answer rather than as
   something won, and the fill took the option's own colour away, which is what
   the design keeps. Same change as `choice`, for the same reason. */
.gs-selector__option[data-gs-state='rewarded'],
.gs-selector__face[data-gs-state='rewarded'],
.gs-selector__trigger[data-gs-state='rewarded'] {
  box-shadow: var(--gs-depth-reward);
  /* The ring, the glow and the badge all extend past the control's own box, and
     a segmented track puts the options shoulder to shoulder, so without this the
     neighbour painted after it covers them. */
  z-index: 1;
}

/* Outside the corner, not inside it: inside, the amount is another line of text
   competing with the label. The option is the positioned ancestor and neither
   `.gs-selector` nor `.gs-selector__track` clips. */
.gs-selector__reward {
  position: absolute;
  /* One step out rather than two, unlike `choice`: a segmented track's gap is
     `space-2`, so two steps would land the badge on top of the next option
     rather than in the gutter beside it. */
  top: calc(-1 * var(--gs-space-1));
  right: calc(-1 * var(--gs-space-1));
  padding: var(--gs-space-1) var(--gs-space-2);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: 1;
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* -- locked and disabled -------------------------------------------------- */
/* Locked keeps its shape and shows a padlock. Only disabled goes flat. */
.gs-selector__option[data-gs-locked='true'],
.gs-selector__trigger[data-gs-locked='true'] { cursor: not-allowed; }

.gs-selector__option[data-gs-disabled='true'],
.gs-selector__trigger[data-gs-disabled='true'],
.gs-selector[data-gs-disabled='true'] .gs-selector__step,
.gs-selector[data-gs-disabled='true'] .gs-selector__face {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}

/* -- text ----------------------------------------------------------------- */
.gs-selector__label { font: inherit; }

.gs-selector__detail {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
  text-transform: none;
}

/* The face and the trigger carry the glyph in the same corner an option does,
   and both lay their label out centred or full width, so the label needs the
   corner kept clear of it. */
.gs-selector__face[data-gs-state],
.gs-selector__trigger[data-gs-state] {
  padding-right: calc(var(--gs-space-4) + var(--gs-size-icon-control));
}

.gs-selector__glyph {
  position: absolute;
  top: var(--gs-space-2);
  right: var(--gs-space-2);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* -- the separate commit -------------------------------------------------- */
/* The offset base collapses and the face travels down by the same amount, so
   the face lands where the base was. */
.gs-selector__commit {
  align-items: center;
  min-height: var(--gs-size-action);
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: 0;
  box-shadow: var(--gs-depth-pressable);
}

.gs-selector__commit:hover { background: var(--gs-color-interactive-hover); }

.gs-selector__commit:active {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}
